import{_ as e,o as t,c as o,aw as r}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Архитектура среды выполнения JS","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/event-loop/main/info.md","filePath":"wiki/dev-commit/js/event-loop/main/info.md"}'),i={name:"wiki/dev-commit/js/event-loop/main/info.md"};function l(n,a,s,c,p,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="архитектура-среды-выполнения-js" tabindex="-1">Архитектура среды выполнения JS <a class="header-anchor" href="#архитектура-среды-выполнения-js" aria-label="Permalink to &quot;Архитектура среды выполнения JS&quot;">​</a></h1><h4 id="видео" tabindex="-1">Видео <a class="header-anchor" href="#видео" aria-label="Permalink to &quot;Видео&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://www.youtube.com/watch?v=8aGhZQkoFbQ" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=8aGhZQkoFbQ</a><a href="https://www.youtube.com/watch?v=cCOL7MC4Pl0" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=cCOL7MC4Pl0</a></p></div><h4 id="статьи" tabindex="-1">Статьи <a class="header-anchor" href="#статьи" aria-label="Permalink to &quot;Статьи&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://dev.to/lydiahallie/javascript-visualized-event-loop-3dif" target="_blank" rel="noreferrer">https://dev.to/lydiahallie/javascript-visualized-event-loop-3dif</a><a href="https://developer.mozilla.org/ru/docs/Web/JavaScript/EventLoop" target="_blank" rel="noreferrer">https://developer.mozilla.org/ru/docs/Web/JavaScript/EventLoop</a><a href="https://habr.com/ru/post/461401/" target="_blank" rel="noreferrer">https://habr.com/ru/post/461401/</a><a href="https://stasonmars.ru/javascript/polnoe-ponimanie-syncronnogo-i-asyncronnogo-javascript-s-async-await/" target="_blank" rel="noreferrer">https://stasonmars.ru/javascript/polnoe-ponimanie-syncronnogo-i-asyncronnogo-javascript-s-async-await/</a></p></div><h2 id="определения" tabindex="-1">Определения <a class="header-anchor" href="#определения" aria-label="Permalink to &quot;Определения&quot;">​</a></h2><ul><li>JS - однопоточная среда выполнения (runtime). Call Stack один и он может делать одну вещь в единицу времени. Одна инструкция за раз</li><li>Используется очередь функций обратного вызова</li><li>Суть блокирования - когда какие то функции занимают Call Stack</li><li>Каждая веб-страница представляет из себя основной поток (Main Thread)</li><li>Движок браузера выполняет JavaScript в одном потоке. Он не может поставить обработку события на паузу, переключиться на другое событие, а после возобновить выполнение первого. Все события обрабатываются последовательно и каждое до конца</li><li>В каждом окне выполняется только один главный поток, который занимается выполнением JavaScript, отрисовкой и работой с DOM. Он выполняет команды последовательно, может делать только одно дело одновременно и блокируется при выводе модальных окон, таких как alert В браузерах события добавляются в очередь в любое время, если событие произошло, а так же если у него есть обработчик. В случае, если обработчика нет – событие потеряно. Так, клик по элементу, имеющему обработчик события по событию click , добавит событие в очередь, а если обработчика нет – то и событие в очередь не попадет</li></ul>',7)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
